"""Inferred profiles, plans, paired judgements and system layers."""
from write_elements import write
import sys

def author(k):
 if k=='architecture':
  css='''/* Inferred from replica10 stepped rows, replica18 title dividers and replica06 capsules. */
ROOT{container-type:size;container-name:od-arch;display:flex;flex-direction:column;justify-content:center;gap:var(--gap-sm);min-width:0;min-height:0;color:var(--ink);padding:1%}ROOT>.layer{display:flex;align-items:center;gap:var(--gap-sm);min-height:0;min-width:0;padding:var(--gap-sm);border-radius:var(--radius-sm);background:var(--n-1)}ROOT>.layer>.name{flex:0 0 24%;margin:0;padding-right:var(--gap-sm);border-right:var(--stroke) solid var(--n-4);font-size:var(--type-18);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}ROOT>.layer>.chip{flex:1;min-width:0;display:flex;align-items:center;justify-content:center;padding:calc(var(--gap-sm)/2);border-radius:999px;background:var(--page);color:var(--n-8);font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track);overflow-wrap:anywhere;text-align:center}ROOT>.layer:first-child{background:var(--a1-1-soft)}@container od-arch (max-width:600px){ROOT>.layer>.name{font-size:var(--type-14)}ROOT>.layer>.chip{font-size:var(--type-12)}}@container od-arch (max-height:250px){ROOT>.layer{padding:calc(var(--gap-sm)/2)}ROOT>.layer>.name{font-size:var(--type-14)}ROOT>.layer>.chip{font-size:var(--type-12)}}
'''
  def row(n):return '<div class="arch" DATA>'+''.join('<div class="layer"><p class="name">'+name+'</p>'+''.join('<span class="chip">'+t+'</span>'for t in chips)+'</div>'for name,chips in [('업무 접점',['고객 접수','상담 응답','진행 안내']),('운영 처리',['담당 조직 배정','예외 요청 검토','이관 기록 대조']),('승인 관리',['책임자 합의','변경 이력 보관','후속 점검']),('공유 기반',['권한 관리','처리 지표 집계','문서 보존'])][:n])+'</div>'
  write(k,'arch',css,'Stacked quiet rows retain the rectangular step rhythm of replica10. A ruled title bay follows replica18 and the service chips use compact capsules; the first layer receives only a pale emphasis surface.',[('three-layers','6x3',row(3)),('four-layers','6x4',row(4))])
 elif k=='versus':
  css='''/* Inferred from replica18 ruled title bays and replica12 dark capsule kicks. */
ROOT{container-type:size;container-name:od-versus;display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:var(--gap-sm);min-width:0;min-height:0;color:var(--ink)}ROOT>.side{display:flex;flex-direction:column;min-width:0;min-height:0;align-items:stretch;gap:var(--gap-sm);padding:var(--pad);background:var(--n-1);border-radius:var(--radius)}ROOT>.side>.name{margin:0;min-height:3em;font-size:var(--type-20);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);padding-bottom:var(--gap-sm);border-bottom:var(--stroke) solid var(--n-4);overflow-wrap:anywhere}ROOT>.side>.list{height:170px;flex:none}ROOT>.side.on{background:var(--a1-1-soft)}ROOT>.vs{align-self:center;display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%;background:var(--n-8);color:var(--page);font-size:var(--type-14);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track-latin)}@container od-versus (max-width:600px){ROOT>.side{padding:var(--gap-sm)}ROOT>.side>.name{font-size:var(--type-16)}ROOT>.side>.list{height:140px}ROOT>.vs{width:28px;height:28px;font-size:var(--type-12)}}@container od-versus (max-height:250px){ROOT>.side{gap:calc(var(--gap-sm)/2)}ROOT>.side>.name{font-size:var(--type-16);min-height:2.8em}ROOT>.side>.list{height:110px}}
'''
  def row(long=False):
   return '<div class="versus" DATA>'+''.join('<div class="side'+(' on'if i else'')+'"><p class="name">'+n+'</p><div class="list divided" data-el="onboard-docket-list">'+''.join('<div class="item"><p class="name">'+t+'</p></div>'for t in lines)+'</div></div>'+('<b class="vs">VS</b>'if i==0 else'')for i,(n,lines) in enumerate([('부서별 개별 검토',['담당자가 메일로 이력 요청','예외 승인 근거를 별도 보관']),('공유된 승인 기록'+('과 통합 점검 기준'if long else''),['같은 근거로 이관 범위 합의','처리 지표와 변경 사유 연결'])]))+'</div>'
  write(k,'versus',css,'Two ruled title bays compare operational approaches. The recommended side receives the same pale accent surface as source cards, while a small dark circular VS joins the pair without creating a separate scene.',[('handoff-methods','8x4',row()),('review-long','8x4',row(True))])
 elif k=='person':
  css='''/* Inferred from replica04 portrait placement and replica17/18 quiet name-and-note hierarchy. */
.people[data-el="onboard-docket-person"]{container-type:size;container-name:od-people;display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-auto-rows:minmax(0,1fr);gap:var(--gap);min-width:0;min-height:0}.people[data-el="onboard-docket-person"]>.person{grid-column:span 4}.people[data-el="onboard-docket-person"]:has(>.person:nth-child(2):last-child)>.person{grid-column:span 6}
.person[data-el="onboard-docket-person"]{container-type:size;container-name:od-person;display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(0,40%) auto auto;align-content:center;justify-items:center;row-gap:var(--gap-sm);min-width:0;min-height:0;color:var(--ink)}.person[data-el="onboard-docket-person"]>.seat{grid-row:1;align-self:center;inline-size:min(90%,40cqh,200px);aspect-ratio:1;max-height:100%;border:var(--stroke) solid var(--n-3);background:var(--n-2)}.person[data-el="onboard-docket-person"]>.seat.portrait{inline-size:min(80%,calc(40cqh * 3 / 4),150px);aspect-ratio:3/4}.person[data-el="onboard-docket-person"]>.name{grid-row:2;margin:0;max-width:100%;font-size:var(--type-20);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);text-align:center;overflow-wrap:anywhere}.person[data-el="onboard-docket-person"]>.note{grid-row:3;margin:0;max-width:94%;font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);text-align:center;color:var(--n-7);overflow-wrap:anywhere}
@container od-person (max-width:260px){.person[data-el="onboard-docket-person"]>.name{font-size:var(--type-16)}.person[data-el="onboard-docket-person"]>.note{font-size:var(--type-12);line-height:var(--label-line)}}@container od-person (max-height:230px){.person[data-el="onboard-docket-person"]>.seat{inline-size:min(70%,38cqh,90px)}.person[data-el="onboard-docket-person"]>.name{font-size:var(--type-16)}.person[data-el="onboard-docket-person"]>.note{font-size:var(--type-12);line-height:var(--label-line)}}
'''
  def row(n):return '<div class="people" DATA>'+''.join('<div class="person" data-el="onboard-docket-person"><div class="seat '+('portrait'if i%2 else'avatar')+'" data-ph="'+str(i+1)+'"></div><p class="name">'+name+'</p><p class="note">'+note+'</p></div>'for i,(name,note) in enumerate([('윤서진 · 운영 총괄','접수 기준과 담당 조직의 이관 범위를 함께 점검합니다.'),('정하린 · 품질 책임','승인 근거를 대조하고 예외 처리 사유를 검토합니다.'),('임도윤 · 서비스 기획','현장 의견을 모아 다음 배포의 보완 항목을 정합니다.')][:n]))+'</div>'
  write(k,'person',css,'A plain portrait or circular avatar sits above an aligned name and restrained business note. The profile is open rather than encased in a generic card, retaining the source letter’s calm signature treatment.',[('three-owners','6x4',row(3)),('two-owners','4x3',row(2))])
 elif k=='pricing':
  css='''/* Inferred from replica18 title-and-explanation card bays and replica12 dark labels. */
.plans[data-el="onboard-docket-pricing"]{container-type:size;container-name:od-plans;display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-auto-rows:minmax(0,1fr);gap:var(--gap-sm);min-width:0;min-height:0}.plans[data-el="onboard-docket-pricing"]>.plan{grid-column:span 4}.plans[data-el="onboard-docket-pricing"]:has(>.plan:nth-child(2):last-child)>.plan{grid-column:span 6}
.plan[data-el="onboard-docket-pricing"]{container-type:size;container-name:od-plan;display:grid;grid-template-rows:auto auto minmax(0,1fr);align-content:center;gap:var(--gap-sm);padding:var(--pad);border-radius:var(--radius);background:var(--n-1);min-width:0;min-height:0;color:var(--ink)}.plan[data-el="onboard-docket-pricing"]>.name{margin:0;padding-bottom:var(--gap-sm);border-bottom:var(--stroke) solid var(--n-4);font-size:var(--type-20);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}.plan[data-el="onboard-docket-pricing"]>.price{display:flex;align-items:baseline;gap:calc(var(--gap-sm)/2);margin:0;flex-wrap:wrap}.plan[data-el="onboard-docket-pricing"]>.price>.fig{font-size:clamp(var(--type-22),calc(11cqw),var(--type-36));font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track)}.plan[data-el="onboard-docket-pricing"]>.price>small{font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track)}.plan[data-el="onboard-docket-pricing"]>.list{align-self:center;min-height:0;height:100%}.plan[data-el="onboard-docket-pricing"].on{background:var(--a1-1-soft);border:var(--stroke) solid var(--a1-4-soft)}.plan[data-el="onboard-docket-pricing"]>.tag{font-size:var(--type-12);font-weight:var(--label-weight);line-height:var(--label-line)}
@container od-plan (max-width:270px){.plan[data-el="onboard-docket-pricing"]>.name{font-size:var(--type-16)}.plan[data-el="onboard-docket-pricing"]>.price>.fig{font-size:var(--type-24)}}
'''
  def row(n):
   return '<div class="plans" DATA>'+''.join('<div class="plan'+(' on'if i==1 else'')+'" data-el="onboard-docket-pricing"><p class="name">'+name+'</p><p class="price"><b class="fig">'+price+'</b><small>만원 / 월</small></p><div class="list divided check" data-el="onboard-docket-list">'+''.join('<div class="item"><p class="name">'+t+'</p></div>'for t in lines)+'</div></div>'for i,(name,price,lines) in enumerate([('팀 운영','18',['접수 채널 두 개 연결','월간 처리 지표 공유']),('조직 운영','42',['담당 조직 여섯 곳 연결','이관 승인 근거 관리']),('통합 운영','79',['전사 요청의 권한 분리','주간 품질 점검 협의'])][:n]))+'</div>'
  write(k,'plan',css,'A ruled name bay and open price retain the source split-card structure. Two concise service rows use the collection’s divided-list treatment, and one recommended plan receives a pale accent surface.',[('three-plans','8x4',row(3)),('two-plans','8x4',row(2))])
 else:raise SystemExit(k)
if __name__=='__main__':author(sys.argv[1])
